const mmss = s => Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0');
const quote = q => q ? '<q>' + esc(String(q).replace(/^["“”'\s]+|["“”'\s.]+$/g, '')) + '</q>' : '';

function head() {
  const d = DATA.deal;
  const sent = { positive: ['pos', 'Positive call'], neutral: ['neu', 'Neutral call'], negative: ['neg', 'Negative call'] }[a.sentiment] || ['neu', ''];
  const talk = a.talk_us !== null && a.talk_us !== undefined ? '<span class="talk">Talk time <span class="bar"><i style="width:' + a.talk_us + '%"></i></span> <b>' + a.talk_us + '%</b> rep · <b>' + (100 - a.talk_us) + '%</b> prospect</span>' : '';
  $('head').innerHTML = '<h1>' + esc(d.name) + '</h1><div class="meta"><span>' + esc(DATA.company) + '</span><span class="pill stage">' + esc(DATA.stage_label) + '</span>'
    + (d.amount ? '<span><b>$' + Number(d.amount).toLocaleString('en-US') + '</b></span>' : '') + '<span>Call ' + esc(DATA.when) + ' · <b>' + mmss(DATA.duration_s) + '</b> · ' + esc(DATA.rep) + '</span>'
    + '<span class="pill ' + sent[0] + '">' + sent[1] + '</span>' + talk + '</div>';
  $('mode').innerHTML = DATA.mode === 'live' ? '' : '<span class="pill test" title="Emails go to the Outbox table and the CRM is the demo tables">Test mode</span>';
}
function left() {
  const done = ['<li><div class="ok">✓</div><div>Call note added to the deal<div class="sub">Summary, BANT, objections, competitors, next steps and risks</div></div></li>']
    .concat(applied.changes.map(c => '<li><div class="ok">✓</div><div>' + esc(c.label) + ': ' + esc(c.from) + '<span class="arrow">→</span><b>' + esc(c.to) + '</b>' + (c.quote ? '<div class="sub">' + quote(c.quote) + '</div>' : '') + '</div></li>'))
